	startChunk := offset / coverageChunkSize
	endChunk := (offset + size - 1) / coverageChunkSize
	for chunk := startChunk; chunk <= endChunk; chunk++ {
		idx, ok := lc.chunkMap[chunk]
		if !ok {
			return false
		}
		if lc.bits[idx/64]&(1<<uint(idx%64)) == 0 {
			return false
		}
	}
	return true
}

