def _split_decl_list(text: str) -> List[str]:
    """Split 'A(LDA,*),B(LDB,*),C(LDC,*)' into individual items."""
    items: List[str] = []
    depth = 0
    current: List[str] = []
    for ch in text:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        if ch == "," and depth == 0:
            items.append("".join(current).strip())
            current = []
        else:
            current.append(ch)
    if current:
        items.append("".join(current).strip())
    return [i for i in items if i]

