pub fn write_file(&self, path: &Path, data: &[u8]) -> Result<()> {
    self.validate_path(path)?;
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .mode(FILE_MODE)
        .open(path)?;
    file.write_all(data)?;
    // Enforce permissions even if the file already existed.
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(FILE_MODE))?;
    Ok(())
}

fn validate_path(&self, path: &Path) -> Result<()> {
    // Try to canonicalize the full path first.
    if let Ok(canonical_path) = std::fs::canonicalize(path)
        && canonical_path.starts_with(&self.canonical_base)
    {
        return Ok(());
    }

    // For paths that don't exist yet, canonicalize the parent.
    if let Some(parent) = path.parent()
        && let Ok(canonical_parent) = std::fs::canonicalize(parent)
        && canonical_parent.starts_with(&self.canonical_base)
    {
        return Ok(());
    }

    Err(crate::error::StorageError::Other(format!(
        "path outside storage root: {}",
        path.display()
    )))
}

pub fn delete_file(&self, path: &Path) -> Result<u64> {
    // Validate before any I/O to avoid leaking metadata for paths outside
    // the storage root. If validation fails because the file (and its
    // parent) are already gone, that's a benign NotFound — return Ok(0).
    if let Err(e) = self.validate_path(path) {
        if !path.exists()
            && path
                .parent()
                .map(|p| !p.exists())
                .unwrap_or(false)
        {
            return Ok(0);
        }
        return Err(e);
    }
    let size = match std::fs::metadata(path) {
        Ok(meta) => meta.len(),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(e.into()),
    };
    match std::fs::remove_file(path) {
        Ok(()) => Ok(size),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(0),
        Err(e) => Err(e.into()),
    }
}

