def _check_ssrf(url: str) -> str | None:
    """
    Return the blocked hostname/IP if the URL targets an internal/metadata
    service, otherwise None.
    """
    try:
        parsed = urlparse(url)
        host = parsed.hostname or ""
    except Exception:
        return None

    # Strip placeholders before resolving
    host_clean = re.sub(r"\{[^}]+\}", "", host).strip(".")

    if host_clean in _SSRF_BLOCKED:
        return host_clean

    # Block private IP ranges
    try:
        addr = ipaddress.ip_address(host_clean)
        if addr.is_private or addr.is_loopback or addr.is_link_local:
            return host_clean
    except ValueError:
        pass

    return None

def replacer(m: re.Match[str]) -> str:
    name = m.group(1)
    # Params take priority, then env-level credentials
    if name in params:
        return str(params[name])
    if name in creds:
        return creds[name]
    # Fall back to env var of the same name (single-tenant mode)
    import os
    env_val = os.environ.get(name)
    if env_val is not None:
        return env_val
    raise MatimoError(
        f"Missing value for placeholder '{{{name}}}'",
        ErrorCode.INVALID_PARAMETER,
        {"placeholder": name},
    )

