    raw = fs.readFileSync(filePath, 'utf-8');
  } catch (err) {
    throw new MatimoError(
      `Cannot read policy file "${filePath}": ${(err as NodeJS.ErrnoException).message}`,
      ErrorCode.INVALID_SCHEMA,
      { filePath }
    );

